begin;
create temp table correction_fixture as select gen_random_uuid() as order_id,gen_random_uuid() as operation_id,p.id as product_id,p.stock as original_stock,p.unit_cost,p.name,p.unit,p.department,studio_access_private.inventory_order_reserved(p.id) as original_reserved from public.inventory_products p where p.deleted_at is null and p.currency='USD' and p.stock-studio_access_private.inventory_order_reserved(p.id)>=3 limit 1;
grant select on correction_fixture to authenticated;
insert into public.inventory_orders(id,number,created_by,created_by_name,area,purpose,recipient_name,delivery_location,needed_on,notes,submission) overriding system value select order_id,-990000001,'6418ad20-d0e8-49c0-8d9a-e1da3daf71b6','Test rollback','Generales','area','Receptor','Oficina comercial',current_date,'Prueba transaccional',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('product_id',product_id,'quantity',1))) from correction_fixture;
insert into public.inventory_order_items(order_id,product_id,product_name,unit,requested_quantity,unit_cost_reference) select order_id,product_id,name,unit,1,unit_cost from correction_fixture;
set local role authenticated;
do $$
declare f record;payload jsonb;bad boolean;counts jsonb;
begin
 select * into strict f from correction_fixture;
 payload:=jsonb_build_object('area','Generales','purpose','area','recipient_name','Receptor corregido','recipient_id',null,'delivery_location','Oficina comercial','notes','Corregido','items',jsonb_build_array(jsonb_build_object('product_id',f.product_id,'quantity',2)));
 perform set_config('request.jwt.claim.sub','6418ad20-d0e8-49c0-8d9a-e1da3daf71b6',true);
 bad:=false;begin perform public.inventory_order_return(f.order_id,'Corregir cantidad',1);exception when insufficient_privilege then bad:=true;end;assert bad,'Own return permitted';
 perform set_config('request.jwt.claim.sub','a0ee4b57-1f73-480b-bc68-0aa034d19bda',true);
 bad:=false;begin perform public.inventory_order_return(f.order_id,' ',1);exception when raise_exception then bad:=true;end;assert bad,'Empty return note permitted';
 perform public.inventory_order_notifications(array[f.order_id]);
 perform public.inventory_order_return(f.order_id,'Corregir cantidad',1);
 perform public.inventory_order_return(f.order_id,'Corregir cantidad',1);
 assert (select status='returned' from public.inventory_orders where id=f.order_id),'Not returned';
 assert (select count(*)=1 from public.inventory_order_events where order_id=f.order_id and event='returned'),'Duplicate return';
 bad:=false;begin perform public.inventory_order_resubmit(f.order_id,1,f.operation_id,payload);exception when insufficient_privilege then bad:=true;end;assert bad,'Another user edited returned order';
 perform set_config('request.jwt.claim.sub','6418ad20-d0e8-49c0-8d9a-e1da3daf71b6',true);
 counts:=public.inventory_order_notifications();assert (counts->>'unseen_corrections')::integer>=1,'Creator notice absent';
 perform public.inventory_order_notifications(array[f.order_id]);
 bad:=false;begin perform public.inventory_order_resubmit(f.order_id,1,gen_random_uuid(),jsonb_set(payload,'{items,0,quantity}',to_jsonb(f.original_stock+1000)));exception when raise_exception then bad:=true;end;assert bad,'Overstock correction permitted';
 assert (select requested_quantity=1 from public.inventory_order_items where order_id=f.order_id),'Failed edit removed old items';
 perform public.inventory_order_resubmit(f.order_id,1,f.operation_id,payload);
 perform public.inventory_order_resubmit(f.order_id,1,f.operation_id,payload);
 assert (select status='pending' and revision=2 and number=-990000001 from public.inventory_orders where id=f.order_id),'Identity or version not preserved';
 assert (select count(*)=1 from public.inventory_order_events where order_id=f.order_id and event='resubmitted'),'Duplicate resubmission';
 assert (select (details->'snapshot'->'items'->0->>'requested_quantity')::numeric=1 from public.inventory_order_events where order_id=f.order_id and event='returned'),'Previous version lost';
 assert (select requested_quantity=2 and approved_quantity=0 from public.inventory_order_items where order_id=f.order_id),'Corrected lines not saved';
 assert (select stock=f.original_stock from public.inventory_products where id=f.product_id),'Stock changed';
 assert (select (x->>'reserved')::numeric from jsonb_array_elements(public.inventory_order_catalog()) x where x->>'id'=f.product_id::text)=f.original_reserved,'Reservation changed';
 perform set_config('request.jwt.claim.sub','a0ee4b57-1f73-480b-bc68-0aa034d19bda',true);
 assert not exists(select 1 from public.inventory_order_reads where order_id=f.order_id),'Approver read receipts not reset';
 perform public.inventory_order_return(f.order_id,'Otro ajuste',2);
 perform set_config('request.jwt.claim.sub','6418ad20-d0e8-49c0-8d9a-e1da3daf71b6',true);
 bad:=false;begin perform public.inventory_order_resubmit(f.order_id,1,gen_random_uuid(),payload);exception when raise_exception then bad:=true;end;assert bad,'Stale correction permitted';
 perform public.inventory_order_resubmit(f.order_id,2,gen_random_uuid(),payload);
 perform set_config('request.jwt.claim.sub','a0ee4b57-1f73-480b-bc68-0aa034d19bda',true);
 bad:=false;begin perform public.inventory_order_decide_versioned(f.order_id,2,'reject','{}','No procede');exception when raise_exception then bad:=true;end;assert bad,'A stale decision was accepted';
 perform public.inventory_order_decide_versioned(f.order_id,3,'reject','{}','No procede');
end $$;

select set_config('request.jwt.claim.sub','6418ad20-d0e8-49c0-8d9a-e1da3daf71b6',true);
do $$declare f record;bad boolean:=false;begin select * into f from correction_fixture;begin perform public.inventory_order_resubmit(f.order_id,3,gen_random_uuid(),'{}');exception when raise_exception then bad:=true;end;assert bad,'Rejected order reopened';end $$;
rollback;
select 'Correction lifecycle, snapshots, notifications, stock guards, idempotency, authorization, stale edits and rejection lock verified; rolled back' as verification;
